function errorInfo(error) {
  // Realm-agnostic AND total: a host-realm Error thrown into the vm-realm
  // producer is not an instanceof the producer realm Error, so never gate on
  // instanceof; and every property read on the thrown value is individually
  // guarded, because a hostile object or Proxy can throw from its code,
  // message, or name getter (or from a get trap) and must not make this
  // normaliser throw out of failure handling. The contract is the bare
  // message plus any string errno code, for host Errors, vm Errors, plain
  // error objects, hostile thrown objects, and non-object throws alike;
  // when no message can be read safely the fixed fallback is used.
  let code = null;
  let message = 'unknown error';
  try {
    const isObjectLike = error !== null && (typeof error === 'object' || typeof error === 'function');
    if (!isObjectLike) {
      if (typeof error === 'string') message = error;
      else { try { message = String(error); } catch { message = 'unknown error'; } }
      return { code, message: typeof message === 'string' ? message : 'unknown error' };
    }
    try {
      const value = error.code;
      if (typeof value === 'string') code = value;
    } catch { /* a hostile code getter leaves code null */ }
    try {
      const value = error.message;
      if (typeof value === 'string' && value.length > 0) return { code, message: value };
    } catch { /* a hostile message getter falls through to String */ }
    let text;
    try { text = String(error); } catch { text = 'unknown error'; }
    if (typeof text !== 'string') text = 'unknown error';
    let name = null;
    try {
      const value = error.name;
      if (typeof value === 'string' && value.length > 0) name = value;
    } catch { /* a hostile name getter disables prefix stripping */ }
    if (name && text.startsWith(`${name}: `)) text = text.slice(name.length + 2);
    message = text;
    return { code, message };
  } catch {
    return { code, message };
  }
}

